// Filtra las opciones de un campo basándose en las selecciones actuales del equipo
export function getFilteredOptions(fieldName, selections, allOptions) {
  let filtered = null;

  for (const [srcField, srcValue] of Object.entries(selections)) {
    if (!srcValue || srcField === fieldName) continue;
    const rule = COMPAT[srcField]?.[srcValue]?.[fieldName];
    if (rule) {
      filtered = filtered ? filtered.filter(v => rule.includes(v)) : [...rule];
    }
  }

  return filtered !== null ? filtered : allOptions;
}

